// T48: 발사음 파일 (base64 WAV, 16bit mono 44.1kHz). 제출본이 HTML 한 파일이라 인라인.
// 원본: 사용자 제공 mp3(강한.mp3 → CS형, 중간.mp3 → PUBG형). 각각 3발 연사 녹음이라 마지막 1발만 잘라 썼다(자연 잔향 포함).
// fire_d2(루트슈터형)는 녹음이 없어 fire_pubg를 피치 ×1.3·240 ms로 가공한 것(make_d2.py).
// 생성: scratchpad convert.py — 잘라낸 wav는 assets/*.wav 에 같이 둔다. 손으로 고치지 말 것.
export const CLIPS = {
  // fire_cs: 650 ms, 57330 B (원본 550~1200 ms)
  fire_cs: 'data:audio/wav;base64,',
  // fire_pubg: 379 ms, 33502 B (원본 271~650 ms)
  fire_pubg: 'data:audio/wav;base64,',
  // fire_d2: 240 ms, 21212 B (가공)
  fire_d2: 'data:audio/wav;base64,',
};
